101	async function answerFrame(
102	  ws: WebSocket,
103	  session: ChatSession,
104	  validation: ValidationResult,
105	  sessionStore?: SessionStore
106	): Promise<void> {
107	  if (!validation.valid) {
108	    log.warn('message', 'validation failed', {error: validation.error});
109	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
110	    return;
111	  }
112	
113	  const message = validation.data;
114	  if (message.type === 'ping') {
115	    handlePing(ws, message.timestamp);
116	    return;
117	  }
118	  if (message.type === 'list_sessions') {
119	    await handleListSessions(ws, session, message, sessionStore);
120	  }
121	}
122	
123	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
124	function isUserMessageFrame(rawMessage: unknown): boolean {
125	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
126	}
127	
128	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
129	  try {
130	    await action();
131	  } catch (error) {
132	    const message = error instanceof Error ? error.message : 'Unknown error';
133	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
134	    log.error('message', 'handling error', {error: message, code});
135	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
136	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
137	      return;
138	    }
139	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
140	  }
141	}
142	
143	async function handleUserMessage(
144	  ws: WebSocket,
145	  session: ChatSession,
146	  orchestrator: ChatOrchestrator,
147	  content: string,
148	  signal: AbortSignal | undefined
149	): Promise<void> {
150	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
151	
152	  const userEntry = createUserEntry(content);
153	  const userIndex = appendEntry(session, userEntry);
154	  sendUpsert(ws, userIndex, userEntry);
155	
156	  const parser = new ThinkingTagParser();
157	  const state: StreamState = {
158	    thinkingIndex: null,
159	    assistantIndex: null,
160	    suppressOutput: false,
161	    sentAssistantIndices: [],
162	  };
163	
164	  let textChunkCount = 0;
165	
166	  try {
167	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
168	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
169	      if (signal?.aborted) break;
170	      textChunkCount = logChunk(chunk, textChunkCount);
171	      processChunk(ws, session, state, parser, chunk);
172	    }
173	  } finally {
174	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
175	    flushHeldText(ws, session, state, parser);
176	    closeCutOff(ws, session, state, 'thinkingIndex');
177	    closeCutOff(ws, session, state, 'assistantIndex');
178	  }
179	
180	  if (textChunkCount > 0) {
181	    log.debug('stream', `received ${textChunkCount} text chunks`);
182	  }
183	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
184	}
185	
186	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
187	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
188	  if (chunk.type === 'text') return textChunkCount + 1;
189	
190	  if (textChunkCount > 0) {
191	    log.debug('stream', `received ${textChunkCount} text chunks`);
192	  }
193	
194	  if (chunk.type === 'tool_result') {
195	    log.debug('stream', 'tool_result chunk', {
196	      messageCount: chunk.clientMessages.length,
197	      types: chunk.clientMessages.map(m => m.type),
198	    });
199	    return 0;
200	  }
201	
202	  log.debug('stream', 'chunk', {type: chunk.type});
203	  return 0;
204	}
205	
206	function processChunk(
207	  ws: WebSocket,
208	  session: ChatSession,
209	  state: StreamState,
210	  parser: ThinkingTagParser,
211	  chunk: MessageChunk
212	): void {
213	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
214	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
215	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
216	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
217	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
218	}
219	
220	function processTextChunk(
221	  ws: WebSocket,
222	  session: ChatSession,
223	  state: StreamState,
224	  parser: ThinkingTagParser,
225	  text: string
226	): void {
227	  const segments = parser.push(text);
228	  for (const segment of segments) {
229	    handleTextSegment(ws, session, state, segment);
230	  }
231	}
232	
233	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
234	  if (segment.type === 'thinking') {
235	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
236	    return;
237	  }
238	  commitAndClear(ws, session, state, 'thinkingIndex');
239	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
240	}
241	
242	function streamSegment(
243	  ws: WebSocket,
244	  session: ChatSession,
245	  state: StreamState,
246	  key: StateIndexKey,
247	  createEntry: EntryFactory,
248	  content: string
249	): void {
250	  const isNew = initSegment(session, state, key, createEntry);
251	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
252	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
253	  appendDelta(session, state[key]!, content);
254	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
255	}
256	
257	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
258	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
259	  markSuppressed(session, index);
260	  sendSkip(ws, index);
261	}
262	
263	function markSuppressed(session: ChatSession, index: number): void {
264	  const entry = session.entries[index];
265	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
266	}
267	
268	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
269	  if (state[key] !== null) return false;
270	  state[key] = appendEntry(session, createEntry());
271	  return true;
272	}
273	
274	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
275	  const index = state[key];
276	  if (index === null) return;
277	
278	  commitEntry(session, index);
279	  state[key] = null;
280	
281	  // Only what the client received can be retracted, and only assistant entries.
282	  if (state.suppressOutput) return;
283	
284	  sendCommit(ws, index);
285	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
286	}
287	
288	function processToolUseChunk(
289	  ws: WebSocket,
290	  session: ChatSession,
291	  toolCall: {name: string; input: Record<string, unknown>}
292	): void {
293	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
294	  const toolIndex = appendEntry(session, toolEntry);
295	  sendUpsert(ws, toolIndex, toolEntry);
296	}
297	
298	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
299	  for (const msg of clientMessages) {
300	    log.debug('stream', 'forwarding client message to frontend', {
301	      type: msg.type,
302	      index: 'index' in msg ? msg.index : undefined,
303	    });
304	    sendJson(ws, msg);
305	  }
306	}
307	
308	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
309	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
310	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
311	  commitOpenEntries(ws, session, state);
312	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
313	
314	  for (const idx of state.sentAssistantIndices) {
315	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
316	    markSuppressed(session, idx);
317	  }
318	
319	  state.sentAssistantIndices = [];
320	  state.suppressOutput = true;
321	}
322	
323	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
324	  flushHeldText(ws, session, state, parser);
325	  commitOpenEntries(ws, session, state);
326	}
327	
328	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
329	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
330	  for (const segment of parser.flush()) {
331	    handleTextSegment(ws, session, state, segment);
332	  }
333	}
334	
335	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
336	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
337	  const index = state[key];
338	  if (index === null) return;
339	  markTruncated(session, index);
340	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
341	  commitAndClear(ws, session, state, key);
342	}
343	
344	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
345	  commitAndClear(ws, session, state, 'thinkingIndex');
346	  commitAndClear(ws, session, state, 'assistantIndex');
347	}
348	
349	async function handleListSessions(
350	  ws: WebSocket,
351	  session: ChatSession,
352	  message: {type: 'list_sessions'; limit?: number; before?: {updatedAt: string | number; sessionId: string}},
353	  sessionStore?: SessionStore
354	): Promise<void> {
355	  if (!sessionStore?.listFor) {
356	    sendJson(ws, {type: 'session_list', sessions: []});
357	    return;
358	  }
359	
360	  try {
361	    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
362	    const sessions = summaries.map(summary => ({
363	      sessionId: summary.sessionId,
364	      createdAt: summary.createdAt instanceof Date ? summary.createdAt.toISOString() : summary.createdAt,
365	      updatedAt: summary.updatedAt instanceof Date ? summary.updatedAt.toISOString() : summary.updatedAt,
366	      entryCount: summary.entryCount,
367	    }));
368	    sendJson(ws, {type: 'session_list', sessions});
369	  } catch (error) {
370	    log.error('ws', 'listFor failed', {
371	      userId: session.userId,
372	      error: error instanceof Error ? error.message : 'Unknown error',
373	    });
374	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
375	  }
376	}
377	
378	function handlePing(ws: WebSocket, timestamp: number): void {
379	  ws.send(JSON.stringify({type: 'pong', timestamp}));
380	}
