1	import {WebSocket, WebSocketServer} from 'ws';
2	import {IncomingMessage} from 'http';
3	import {Duplex} from 'stream';
4	import {v4 as uuidv4} from 'uuid';
5	import type {WsAuthenticator} from '../../types/auth.js';
6	import type {SessionStore} from '../../types/sessionStore.js';
7	import type {ConnectedMessage} from '../../types/messages.js';
8	import type {AuthenticatedUser, ChatSession} from '../../types/session.js';
9	import {ErrorCodes} from '../../types/session.js';
10	import {sendError} from './sender.js';
11	import {isValidWsPath, rejectSocket, parseWsData, sessionIdFromUpgrade, newSessionRequested} from './helpers.js';
12	import {credentialFromSubprotocol} from './subprotocol.js';
13	import {replayEntries, resumableSession, resumeFields} from './sessionResume.js';
14	import type {ConnectInfo, SessionResumeOptions} from './sessionResume.js';
15	import {log} from '../../shared/logger.js';
16	
17	export interface ExtWebSocket extends WebSocket {
18	  isAlive: boolean;
19	  userId: string | number;
20	  workspaceId?: string | number;
21	  authHeaders?: {
22	    cookie?: string;
23	    authorization?: string;
24	    host?: string;
25	  };
26	  requestedSessionId?: string;
27	  startNewSession?: boolean;
28	}
29	
30	export interface ConnectionHandlerDeps {
31	  wsAuth: WsAuthenticator;
32	  sessionStore: SessionStore;
33	  /** `signal` is the connection's own, aborted when its socket closes (specs/hal-engine-abandon-on-close/spec.md). */
34	  handleMessage: (
35	    ws: WebSocket,
36	    session: import('../../types/session.js').ChatSession,
37	    rawMessage: unknown,
38	    signal?: AbortSignal
39	  ) => Promise<void>;
40	  basePath: string;
41	  onConnect?: (session: import('../../types/session.js').ChatSession, connection: ConnectInfo) => void | Promise<void>;
42	  onDisconnect?: (sessionId: string) => void | Promise<void>;
43	  resume?: SessionResumeOptions;
44	}
45	export function createUpgradeHandler(wss: WebSocketServer, deps: ConnectionHandlerDeps) {
46	  return function handleUpgrade(request: IncomingMessage, socket: Duplex, head: Buffer): void {
47	    // Nothing may throw out of this listener: the `upgrade` event has no catch above it, so a throw ends the process.
48	    if (!request.headers.host || !isValidWsPath(request.url || '', deps.basePath)) {
49	      rejectSocket(socket, '400 Bad Request');
50	      return;
51	    }
52	
53	    authenticate(deps.wsAuth, request)
54	      .then(user => {
55	        if (!user) {
56	          rejectSocket(socket, '401 Unauthorized');
57	          return;
58	        }
59	
60	        wss.handleUpgrade(request, socket, head, ws => {
61	          const extWs = ws as ExtWebSocket;
62	          extWs.userId = user.id;
63	          extWs.workspaceId = user['workspaceId'] as string | number | undefined;
64	          extWs.authHeaders = {
65	            cookie: request.headers.cookie,
66	            authorization: request.headers.authorization || bearerFromWebSocketProtocol(request),
67	            host: (request.headers['x-forwarded-host'] as string | undefined) ?? request.headers.host,
68	          };
69	          extWs.isAlive = true;
70	          if (deps.resume?.enabled) {
71	            extWs.requestedSessionId = sessionIdFromUpgrade(request.url || '', deps.basePath);
72	            extWs.startNewSession = newSessionRequested(request.url || '', deps.basePath);
73	          }
74	          wss.emit('connection', extWs, request);
75	        });
76	      })
77	      .catch((error: unknown) => {
78	        // The type alone: an authenticator's message can carry the credential it was checking.
79	        log.error('ws', 'authenticator failed', {errorType: error instanceof Error ? error.name : typeof error});
80	        rejectSocket(socket, '500 Internal Server Error');
81	      });
82	  };
83	}
84	
85	// Async, so a synchronous throw becomes a rejection (answered 500) and a user returned without a promise still resolves.
86	async function authenticate(wsAuth: WsAuthenticator, request: IncomingMessage): Promise<AuthenticatedUser | null> {
87	  return wsAuth(request);
88	}
89	
90	function bearerFromWebSocketProtocol(req: IncomingMessage): string | undefined {
91	  const token = credentialFromSubprotocol(req.headers['sec-websocket-protocol']);
92	  return token ? `Bearer ${token}` : undefined;
93	}
94	
95	export function createConnectionHandler(deps: ConnectionHandlerDeps, examplePrompts: string[]) {
96	  return function handleConnection(ws: ExtWebSocket): void {
97	    // The listener stays synchronous: an async one rejects into the emitter, and node ends the process on that.
98	    openSession(deps, examplePrompts, ws).catch((error: unknown) => {
99	      log.error('ws', 'connection setup failed', {error: messageOf(error)});
100	      // Resumed before closing: a paused socket never reads the close frame it would be waiting for.
101	      ws.resume();
102	      ws.close(1011, 'Connection setup failed');
103	    });
104	  };
105	}
106	
107	// The sockets open on each session, oldest first: a resumed session can be open on more than one at once.
108	const openSockets = new WeakMap<ChatSession, ExtWebSocket[]>();
109	
110	async function openSession(deps: ConnectionHandlerDeps, examplePrompts: string[], ws: ExtWebSocket): Promise<void> {
111	  // A requested id is never adopted for a new session: that would be session fixation.
112	  let sessionId = uuidv4();
113	  const state = {closed: false, settled: false, notified: false, delivered: false};
114	  const held: {session?: ChatSession; socket: ExtWebSocket} = {socket: ws};
115	  // One per connection, not per message or session: a close abandons the turn in flight and every message queued behind it.
116	  const connection = new AbortController();
117	
118	  ws.on('error', (error: Error) => {
119	    log.error('ws', 'connection error', {sessionId, error: error.message});
120	  });
121	
122	  ws.on('pong', () => {
123	    ws.isAlive = true;
124	  });
125	
126	  ws.on('close', () => {
127	    // First, so the turn stops before the session is torn down and before onDisconnect.
128	    connection.abort();
129	    state.closed = true;
130	    log.info('ws', 'disconnected', {sessionId});
131	    if (state.settled) endSession(deps, sessionId, state, held);
132	  });
133	
134	  // Paused across the await so a frame arriving before the message listener exists is buffered, not dropped.
135	  ws.pause();
136	
137	  const outcome = await resumableSession(deps.sessionStore, ws, deps.resume);
138	  const resumed = outcome.session;
139	  if (resumed) sessionId = resumed.sessionId;
140	  const session = resumed ?? (await createSession(deps, sessionId, ws));
141	  state.settled = true;
142	
143	  if (session === undefined) {
144	    // Resumed before closing: ws.close() on a paused socket waits for a close frame it can never read.
145	    ws.resume();
146	    ws.close(1011, 'Session store unavailable');
147	    return;
148	  }
149	
150	  // A new session is this socket's from the start; a resumed one only once this socket is known to be open.
151	  if (!resumed) join(session, ws);
152	
153	  if (state.closed) {
154	    // Held first: a store that implements no evict still holds this session, and it carries the caller's credentials.
155	    held.session = session;
156	    await evictUnlessResumed(deps, sessionId, resumed);
157	    endSession(deps, sessionId, state, held);
158	    ws.resume();
159	    return;
160	  }
161	
162	  if (resumed) join(resumed, ws);
163	  held.session = session;
164	
