export function useTestLifecycle(serverArray: Array<ReturnType<typeof createServer>>, clientArray: WebSocket[]): void {
  afterEach(async () => {
    for (const client of clientArray.splice(0)) {
      client.terminate();
      // Allow close handlers to run and complete before proceeding
      await new Promise(resolve => setImmediate(resolve));
    }
    for (const hal of serverArray.splice(0)) {
      const {wss} = hal;
      await eventually(() => wss.clients.size === 0);
      await hal.stop();
    }
  });
}

